class Solution {
public:
    int openLock(vector<string>& deadends, string target) {
        unordered_set<string> dead(deadends.begin(), deadends.end());
        if (dead.count("0000")) return -1;
        if (target == "0000") return 0;

        unordered_set<string> visited;
        queue<string> q;
        q.push("0000");
        visited.insert("0000");
        int turns = 0;

        while (!q.empty()) {
            int sz = q.size();
            turns++;
            for (int i = 0; i < sz; i++) {
                string cur = q.front();
                q.pop();
                for (int j = 0; j < 4; j++) {
                    for (int d = -1; d <= 1; d += 2) {
                        string next = cur;
                        int digit = next[j] - '0';
                        digit = (digit + d + 10) % 10;
                        next[j] = char('0' + digit);
                        if (next == target) return turns;
                        if (!visited.count(next) && !dead.count(next)) {
                            visited.insert(next);
                            q.push(next);
                        }
                    }
                }
            }
        }
        return -1;
    }
};
